{
  "hypotheses": [
    {
      "risk": "The payments table may contain multiple entries for the same order_id, leading to inflated captured_cents.",
      "bug_type": "fanout_join",
      "probe_sql": "SELECT order_id, COUNT(*) AS payment_count FROM payments GROUP BY order_id HAVING COUNT(*) > 1",
      "settles": "If this query returns rows, it confirms the issue; if it returns no rows, the issue is ruled out."
    },
    {
      "risk": "Some completed orders may not have corresponding payment records, leading to an undercount of orders.",
      "bug_type": "missing_filter",
      "probe_sql": "SELECT COUNT(DISTINCT o.order_id) AS orders_without_payments FROM orders o LEFT JOIN payments p ON p.order_id = o.order_id WHERE o.status = 'completed' AND p.order_id IS NULL",
      "settles": "If this query returns a count greater than 0, it confirms the issue; if it returns 0, the issue is ruled out."
    },
    {
      "risk": "Refunds may not be accounted for, leading to discrepancies in captured_cents.",
      "bug_type": "other",
      "probe_sql": "SELECT SUM(amount_cents) AS total_refunds FROM refunds WHERE order_id IN (SELECT order_id FROM orders WHERE status = 'completed')",
      "settles": "If this query returns a non-zero total, it indicates refunds are not considered; if it returns 0, the issue is ruled out."
    },
    {
      "risk": "The query may not account for currency differences, leading to incorrect total captured_cents.",
      "bug_type": "mixed_unit_aggregation",
      "probe_sql": "SELECT currency, SUM(p.amount_cents) AS total_captured FROM payments p JOIN orders o ON p.order_id = o.order_id WHERE o.status = 'completed' GROUP BY currency",
      "settles": "If this query returns more than one currency, it confirms the issue; if it returns only one currency, the issue is ruled out."
    }
  ]
}
